/* ============ DESIGN TOKENS ============ */
const T = {
  bg: "#F1F4F1",
  card: "#FFFFFF",
  border: "#E1E6E1",
  ink: "#10192B",
  muted: "#5B6472",
  navy: "#0B2545",
  navyLight: "#16345F",
  green: "#1E8A5F",
  greenSoft: "#E4F2EA",
  gold: "#C9A227",
  goldSoft: "#FBF2D9",
  coral: "#B23B3B",
  coralSoft: "#F8E9E9",
};

const FONT_DISPLAY = "'Oswald', 'Barlow Condensed', sans-serif";
const FONT_MONO = "'IBM Plex Mono', 'Roboto Mono', monospace";
const FONT_BODY = "'Inter', system-ui, sans-serif";

const GoogleFonts = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500;600;700&display=swap');
    * { box-sizing: border-box; }
    ::-webkit-scrollbar { height: 6px; width: 6px; }
    ::-webkit-scrollbar-thumb { background: #C7CFC7; border-radius: 4px; }
  `}</style>
);

/* ============ SMALL UI PRIMITIVES ============ */
function KpiCard({ icon: Icon, label, value, sub }) {
  return (
    <div
      className="rounded-xl p-4 flex-1 min-w-[140px]"
      style={{ background: T.navy, border: `1px solid ${T.navyLight}` }}
    >
      <div className="flex items-center gap-2 mb-2">
        <Icon size={15} color={T.gold} />
        <span className="text-xs uppercase tracking-wider" style={{ color: "#9FB0C7", fontFamily: FONT_BODY }}>
          {label}
        </span>
      </div>
      <div className="text-3xl font-bold" style={{ color: "#fff", fontFamily: FONT_MONO }}>
        {value}
      </div>
      {sub && (
        <div className="text-xs mt-1" style={{ color: "#7C93B3", fontFamily: FONT_BODY }}>
          {sub}
        </div>
      )}
    </div>
  );
}

function Card({ title, eyebrow, children, className = "" }) {
  return (
    <div
      className={`rounded-xl p-5 ${className}`}
      style={{ background: T.card, border: `1px solid ${T.border}` }}
    >
      {eyebrow && (
        <div className="text-xs uppercase tracking-wider mb-1" style={{ color: T.green, fontFamily: FONT_BODY, fontWeight: 600 }}>
          {eyebrow}
        </div>
      )}
      {title && (
        <div className="text-xl mb-3" style={{ color: T.ink, fontFamily: FONT_DISPLAY, fontWeight: 600 }}>
          {title}
        </div>
      )}
      {children}
    </div>
  );
}

function ResultBadge({ result }) {
  const map = {
    Win: { bg: T.greenSoft, fg: T.green, label: "W" },
    Draw: { bg: T.goldSoft, fg: "#93770F", label: "D" },
    Loss: { bg: T.coralSoft, fg: T.coral, label: "L" },
  };
  const s = map[result] || map.Draw;
  return (
    <span
      className="inline-flex items-center justify-center w-6 h-6 rounded text-xs font-bold"
      style={{ background: s.bg, color: s.fg, fontFamily: FONT_MONO }}
    >
      {s.label}
    </span>
  );
}

function TabButton({ active, onClick, children }) {
  return (
    <button
      onClick={onClick}
      className="px-4 py-2 rounded-lg text-sm whitespace-nowrap transition-colors"
      style={{
        fontFamily: FONT_BODY,
        fontWeight: 600,
        background: active ? T.navy : "transparent",
        color: active ? "#fff" : T.muted,
        border: `1px solid ${active ? T.navy : T.border}`,
      }}
    >
      {children}
    </button>
  );
}

/* ============ TABS ============ */

function OverviewTab() {
  const tt = WC26_DATA.tournamentTotals;
  const stageOrder = ["Group Stage", "Round of 32", "Round of 16"];
  const stageData = stageOrder.map((s) => ({ stage: s.replace("Round of ", "R"), goals: tt.goals_by_stage[s] }));
  const scorers = WC26_DATA.topScorers.slice(0, 8).map((r) => ({ team: r.team, goals: r.goals_for }));

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap gap-3">
        <KpiCard icon={Flame} label="Total Goals" value={tt.total_goals} sub={`${tt.total_matches} matches played`} />
        <KpiCard icon={Target} label="Goals / Match" value={tt.avg_goals_per_match} sub="tournament average" />
        <KpiCard icon={Users} label="Draws" value={`${tt.draws_pct}%`} sub={`${tt.draws} of ${tt.total_matches} — all in Group Stage`} />
        <KpiCard icon={Zap} label="Penalty Shootouts" value={tt.penalty_shootouts} sub="Round of 32 only, so far" />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
        <Card eyebrow="Scoring pattern" title="Goals per match, by stage">
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={stageData} margin={{ left: -10 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} />
              <XAxis dataKey="stage" tick={{ fontFamily: FONT_BODY, fontSize: 12, fill: T.muted }} axisLine={{ stroke: T.border }} tickLine={false} />
              <YAxis tick={{ fontFamily: FONT_MONO, fontSize: 11, fill: T.muted }} axisLine={false} tickLine={false} />
              <Tooltip contentStyle={{ fontFamily: FONT_BODY, borderRadius: 8, border: `1px solid ${T.border}` }} />
              <Bar dataKey="goals" radius={[6, 6, 0, 0]} fill={T.green}>
                <LabelList dataKey="goals" position="top" style={{ fontFamily: FONT_MONO, fontSize: 12, fill: T.ink }} />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </Card>

        <Card eyebrow="Attack" title="Top scorers so far">
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={scorers} layout="vertical" margin={{ left: 10 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={T.border} horizontal={false} />
              <XAxis type="number" tick={{ fontFamily: FONT_MONO, fontSize: 11, fill: T.muted }} axisLine={false} tickLine={false} />
              <YAxis type="category" dataKey="team" width={90} tick={{ fontFamily: FONT_BODY, fontSize: 12, fill: T.ink }} axisLine={false} tickLine={false} />
              <Tooltip contentStyle={{ fontFamily: FONT_BODY, borderRadius: 8, border: `1px solid ${T.border}` }} />
              <Bar dataKey="goals" radius={[0, 6, 6, 0]} fill={T.navy}>
                <LabelList dataKey="goals" position="right" style={{ fontFamily: FONT_MONO, fontSize: 12, fill: T.ink }} />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </Card>
      </div>

      <Card eyebrow="Extremes" title="Records so far">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm" style={{ fontFamily: FONT_BODY, color: T.ink }}>
          {WC26_DATA.highestScoring.slice(0, 1).map((m, i) => (
            <div key={i} className="flex items-start gap-2">
              <Flame size={16} color={T.coral} className="mt-0.5 shrink-0" />
              <span><b>Highest-scoring:</b> {m.team_1} {m.score_1}–{m.score_2} {m.team_2} ({m.total_goals} goals)</span>
            </div>
          ))}
          {WC26_DATA.biggestMargins.slice(0, 1).map((m, i) => (
            <div key={i} className="flex items-start gap-2">
              <Zap size={16} color={T.gold} className="mt-0.5 shrink-0" />
              <span><b>Biggest margin:</b> {m.team_1} {m.score_1}–{m.score_2} {m.team_2} (+{m.goal_margin})</span>
            </div>
          ))}
          <div className="flex items-start gap-2">
            <ShieldCheck size={16} color={T.green} className="mt-0.5 shrink-0" />
            <span><b>Best defense:</b> {WC26_DATA.bestDefense[0].team} — {WC26_DATA.bestDefense[0].goals_against} conceded in {WC26_DATA.bestDefense[0].matches} matches</span>
          </div>
          <div className="flex items-start gap-2">
            <Trophy size={16} color={T.navy} className="mt-0.5 shrink-0" />
            <span><b>Form leader:</b> {WC26_DATA.leaderboard[0].team} — {WC26_DATA.leaderboard[0].wins}-{WC26_DATA.leaderboard[0].draws}-{WC26_DATA.leaderboard[0].losses}, {WC26_DATA.leaderboard[0].points} pts</span>
          </div>
        </div>
      </Card>
    </div>
  );
}

function TeamsTab() {
  const teams = useMemo(() => [...WC26_DATA.leaderboard].sort((a, b) => a.team.localeCompare(b.team)), []);
  const [selected, setSelected] = useState(
    WC26_DATA.leaderboard[0].team
  );
  const teamRow = WC26_DATA.leaderboard.find((t) => t.team === selected);
  const teamMatches = WC26_DATA.factTeamMatch
    .filter((m) => m.team === selected)
    .sort((a, b) => a.date.localeCompare(b.date));

  return (
    <div className="space-y-5">
      <Card>
        <div className="flex flex-wrap items-center gap-3">
          <span className="text-sm" style={{ fontFamily: FONT_BODY, color: T.muted }}>Select team:</span>
          <select
            value={selected}
            onChange={(e) => setSelected(e.target.value)}
            className="px-3 py-2 rounded-lg text-sm"
            style={{ fontFamily: FONT_BODY, border: `1px solid ${T.border}`, color: T.ink, background: "#fff" }}
          >
            {teams.map((t) => (
              <option key={t.team} value={t.team}>{t.team}</option>
            ))}
          </select>
          <span
            className="ml-auto text-xs px-3 py-1 rounded-full font-semibold"
            style={{
              fontFamily: FONT_BODY,
              background: teamRow.still_active ? T.greenSoft : T.coralSoft,
              color: teamRow.still_active ? T.green : T.coral,
            }}
          >
            {teamRow.status}
          </span>
        </div>
      </Card>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <KpiCard icon={Trophy} label="Points" value={teamRow.points} sub={`${teamRow.confederation}`} />
        <KpiCard icon={Target} label="Record" value={`${teamRow.wins}-${teamRow.draws}-${teamRow.losses}`} sub="W-D-L" />
        <KpiCard icon={Flame} label="Goals" value={`${teamRow.goals_for}-${teamRow.goals_against}`} sub="for–against" />
        <KpiCard icon={Zap} label="Goal Diff" value={teamRow.goal_diff >= 0 ? `+${teamRow.goal_diff}` : teamRow.goal_diff} sub={`${teamRow.matches_played} matches played`} />
      </div>

      <Card eyebrow="Match log" title={`${selected} — results so far`}>
        <div className="space-y-2">
          {teamMatches.map((m) => (
            <div
              key={m.match_id}
              className="flex items-center gap-3 text-sm py-2 px-3 rounded-lg"
              style={{ fontFamily: FONT_BODY, background: T.bg }}
            >
              <span className="w-24 shrink-0" style={{ color: T.muted, fontFamily: FONT_MONO, fontSize: 12 }}>{m.date}</span>
              <span className="w-28 shrink-0 text-xs uppercase" style={{ color: T.muted }}>{m.stage.replace("Round of ", "R")}</span>
              <ResultBadge result={m.result} />
              <span className="flex-1" style={{ color: T.ink }}>vs {m.opponent}</span>
              <span style={{ fontFamily: FONT_MONO, color: T.ink, fontWeight: 600 }}>
                {m.goals_for}–{m.goals_against}{m.decided_by_penalties ? " (pens)" : ""}
              </span>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}

function StandingsTab() {
  const groups = useMemo(() => [...new Set(WC26_DATA.groupStandings.map((r) => r.group))].sort(), []);
  const [group, setGroup] = useState(groups[0]);
  const rows = WC26_DATA.groupStandings
    .filter((r) => r.group === group)
    .sort((a, b) => a.group_rank - b.group_rank);

  return (
    <div className="space-y-5">
      <Card>
        <div className="flex flex-wrap gap-2">
          {groups.map((g) => (
            <button
              key={g}
              onClick={() => setGroup(g)}
              className="w-9 h-9 rounded-lg text-sm font-semibold"
              style={{
                fontFamily: FONT_MONO,
                background: group === g ? T.navy : "#fff",
                color: group === g ? "#fff" : T.ink,
                border: `1px solid ${group === g ? T.navy : T.border}`,
              }}
            >
              {g}
            </button>
          ))}
        </div>
      </Card>

      <Card eyebrow={`Group ${group}`} title="Standings">
        <div className="overflow-x-auto">
          <table className="w-full text-sm" style={{ fontFamily: FONT_BODY, borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ color: T.muted, textAlign: "left" }}>
                <th className="pb-2 pr-2">#</th>
                <th className="pb-2 pr-2">Team</th>
                <th className="pb-2 pr-2 text-center">P</th>
                <th className="pb-2 pr-2 text-center">W</th>
                <th className="pb-2 pr-2 text-center">D</th>
                <th className="pb-2 pr-2 text-center">L</th>
                <th className="pb-2 pr-2 text-center">GF</th>
                <th className="pb-2 pr-2 text-center">GA</th>
                <th className="pb-2 pr-2 text-center">GD</th>
                <th className="pb-2 pr-2 text-center">Pts</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => (
                <tr
                  key={r.team}
                  style={{
                    borderLeft: r.group_rank <= 2 ? `3px solid ${T.green}` : "3px solid transparent",
                    background: r.group_rank <= 2 ? T.greenSoft : "transparent",
                  }}
                >
                  <td className="py-2 pr-2" style={{ fontFamily: FONT_MONO, color: T.muted }}>{r.group_rank}</td>
                  <td className="py-2 pr-2 font-semibold" style={{ color: T.ink }}>{r.team}</td>
                  <td className="py-2 pr-2 text-center" style={{ fontFamily: FONT_MONO }}>{r.played}</td>
                  <td className="py-2 pr-2 text-center" style={{ fontFamily: FONT_MONO }}>{r.won}</td>
                  <td className="py-2 pr-2 text-center" style={{ fontFamily: FONT_MONO }}>{r.drawn}</td>
                  <td className="py-2 pr-2 text-center" style={{ fontFamily: FONT_MONO }}>{r.lost}</td>
                  <td className="py-2 pr-2 text-center" style={{ fontFamily: FONT_MONO }}>{r.goals_for}</td>
                  <td className="py-2 pr-2 text-center" style={{ fontFamily: FONT_MONO }}>{r.goals_against}</td>
                  <td className="py-2 pr-2 text-center" style={{ fontFamily: FONT_MONO }}>{r.goal_diff >= 0 ? `+${r.goal_diff}` : r.goal_diff}</td>
                  <td className="py-2 pr-2 text-center font-bold" style={{ fontFamily: FONT_MONO, color: T.ink }}>{r.points}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="flex items-center gap-2 mt-3 text-xs" style={{ fontFamily: FONT_BODY, color: T.muted }}>
          <span className="w-3 h-3 rounded-sm inline-block" style={{ background: T.greenSoft, border: `1px solid ${T.green}` }} />
          Advanced to Round of 32
        </div>
      </Card>
    </div>
  );
}

function ConfederationsTab() {
  const data = WC26_DATA.confederationSummary;
  const winPct = data.map((c) => ({ conf: c.confederation, value: c.win_pct }));
  const goalsPerMatch = data.map((c) => ({ conf: c.confederation, value: c.goals_per_match }));

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
        <Card eyebrow="Performance" title="Win % by confederation">
          <ResponsiveContainer width="100%" height={240}>
            <BarChart data={winPct} margin={{ left: -10 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} />
              <XAxis dataKey="conf" tick={{ fontFamily: FONT_BODY, fontSize: 11, fill: T.muted }} axisLine={{ stroke: T.border }} tickLine={false} />
              <YAxis tick={{ fontFamily: FONT_MONO, fontSize: 11, fill: T.muted }} axisLine={false} tickLine={false} unit="%" />
              <Tooltip contentStyle={{ fontFamily: FONT_BODY, borderRadius: 8, border: `1px solid ${T.border}` }} formatter={(v) => `${v}%`} />
              <Bar dataKey="value" radius={[6, 6, 0, 0]}>
                {winPct.map((entry, i) => (
                  <Cell key={i} fill={entry.value >= 40 ? T.green : entry.value >= 20 ? T.gold : T.coral} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </Card>

        <Card eyebrow="Attack" title="Goals per match by confederation">
          <ResponsiveContainer width="100%" height={240}>
            <BarChart data={goalsPerMatch} margin={{ left: -10 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} />
              <XAxis dataKey="conf" tick={{ fontFamily: FONT_BODY, fontSize: 11, fill: T.muted }} axisLine={{ stroke: T.border }} tickLine={false} />
              <YAxis tick={{ fontFamily: FONT_MONO, fontSize: 11, fill: T.muted }} axisLine={false} tickLine={false} />
              <Tooltip contentStyle={{ fontFamily: FONT_BODY, borderRadius: 8, border: `1px solid ${T.border}` }} />
              <Bar dataKey="value" radius={[6, 6, 0, 0]} fill={T.navy} />
            </BarChart>
          </ResponsiveContainer>
        </Card>
      </div>

      <Card eyebrow="Progression" title="Teams entered vs. advanced, by confederation">
        <div className="overflow-x-auto">
          <table className="w-full text-sm" style={{ fontFamily: FONT_BODY, borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ color: T.muted, textAlign: "left" }}>
                <th className="pb-2 pr-3">Confederation</th>
                <th className="pb-2 pr-3 text-center">Entered</th>
                <th className="pb-2 pr-3 text-center">Reached R32</th>
                <th className="pb-2 pr-3 text-center">Reached R16</th>
                <th className="pb-2 pr-3 text-center">Still Active</th>
              </tr>
            </thead>
            <tbody>
              {data.map((c) => (
                <tr key={c.confederation} style={{ borderTop: `1px solid ${T.border}` }}>
                  <td className="py-2 pr-3 font-semibold" style={{ color: T.ink }}>{c.confederation}</td>
                  <td className="py-2 pr-3 text-center" style={{ fontFamily: FONT_MONO }}>{c.teams_entered}</td>
                  <td className="py-2 pr-3 text-center" style={{ fontFamily: FONT_MONO }}>{c.reached_round_of_32}</td>
                  <td className="py-2 pr-3 text-center" style={{ fontFamily: FONT_MONO }}>{c.reached_round_of_16}</td>
                  <td className="py-2 pr-3 text-center font-bold" style={{ fontFamily: FONT_MONO, color: T.green }}>{c.still_active}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
}

function StorylinesTab() {
  return (
    <div className="space-y-5">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <Card eyebrow="Shock exit" title="Two giants fall on penalties">
          <p className="text-sm" style={{ fontFamily: FONT_BODY, color: T.ink }}>
            Germany and Netherlands — two traditional powerhouses — were both eliminated in the Round of 32 on penalties,
            to Paraguay and Morocco respectively.
          </p>
        </Card>
        <Card eyebrow="Cinderella run" title="Cape Verde's historic run">
          <p className="text-sm" style={{ fontFamily: FONT_BODY, color: T.ink }}>
            A nation of roughly 500,000 people drew 3 of 4 group games and reached the Round of 32 — the best showing of
            any World Cup debutant this tournament.
          </p>
        </Card>
        <Card eyebrow="Record-breaking" title="Messi's record-breaking night">
          <p className="text-sm" style={{ fontFamily: FONT_BODY, color: T.ink }}>
            Argentina's 2–0 win over Austria in the group stage is the match in which Messi set the all-time World Cup
            goalscoring record.
          </p>
        </Card>
        <Card eyebrow="Co-host heartbreak" title="Canada's run ends in the Round of 16">
          <p className="text-sm" style={{ fontFamily: FONT_BODY, color: T.ink }}>
            Morocco eliminated co-host Canada 3–0, ending the host run for one of the tournament's three co-hosts.
          </p>
        </Card>
      </div>

      <Card eyebrow="Penalty shootouts" title="Every shootout so far">
        <div className="space-y-2">
          {WC26_DATA.penaltyMatches.map((m, i) => (
            <div key={i} className="flex items-center gap-3 text-sm py-2 px-3 rounded-lg" style={{ fontFamily: FONT_BODY, background: T.bg }}>
              <span style={{ fontFamily: FONT_MONO, color: T.muted, fontSize: 12 }} className="w-24 shrink-0">{m.date}</span>
              <span className="flex-1" style={{ color: T.ink }}>{m.team_1} vs {m.team_2}</span>
              <span className="font-semibold" style={{ color: T.green }}>{m.winner} won</span>
            </div>
          ))}
        </div>
      </Card>

      <Card eyebrow="Data quality" title="Corrections made during cleaning">
        <div className="space-y-2">
          {WC26_DATA.cleaningLog.map((c, i) => (
            <div key={i} className="flex items-start gap-2 text-sm py-2 px-3 rounded-lg" style={{ fontFamily: FONT_BODY, background: T.coralSoft }}>
              <AlertTriangle size={15} color={T.coral} className="mt-0.5 shrink-0" />
              <span style={{ color: T.ink }}>
                <b>{c.team}</b>: {c.old_eliminated_round} → <b>{c.corrected_eliminated_round}</b>. {c.reason}.
              </span>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}

/* ============ ROOT ============ */
export default function App() {
  const [tab, setTab] = useState("overview");
  const tabs = [
    { id: "overview", label: "Overview" },
    { id: "teams", label: "Team Explorer" },
    { id: "standings", label: "Group Standings" },
    { id: "confederations", label: "Confederations" },
    { id: "storylines", label: "Storylines" },
  ];

  return (
    <div style={{ background: T.bg, minHeight: "100vh", fontFamily: FONT_BODY }}>
      <GoogleFonts />
      <div className="max-w-5xl mx-auto px-4 py-6">
        <div
          className="rounded-2xl p-6 mb-5"
          style={{ background: `linear-gradient(135deg, ${T.navy}, ${T.navyLight})` }}
        >
          <div className="text-xs uppercase tracking-widest mb-1" style={{ color: T.gold, fontFamily: FONT_BODY, fontWeight: 600 }}>
            Data Analysis Dashboard
          </div>
          <div className="text-3xl sm:text-4xl" style={{ color: "#fff", fontFamily: FONT_DISPLAY, fontWeight: 600 }}>
            FIFA World Cup 2026
          </div>
          <div className="text-sm mt-1" style={{ color: "#B8C6DC" }}>
            Snapshot through July 5, 2026 · Group Stage → Round of 16 · 92 matches, 48 teams
          </div>
        </div>

        <div className="flex flex-wrap gap-2 mb-5">
          {tabs.map((t) => (
            <TabButton key={t.id} active={tab === t.id} onClick={() => setTab(t.id)}>
              {t.label}
            </TabButton>
          ))}
        </div>

        {tab === "overview" && <OverviewTab />}
        {tab === "teams" && <TeamsTab />}
        {tab === "standings" && <StandingsTab />}
        {tab === "confederations" && <ConfederationsTab />}
        {tab === "storylines" && <StorylinesTab />}

        <div className="text-center text-xs mt-8 pb-4" style={{ color: T.muted, fontFamily: FONT_BODY }}>
          All figures generated directly from the cleaned dataset — matches_clean.csv, dim_team_summary.csv, group_standings.csv, confederation_summary.csv.
        </div>
      </div>
    </div>
  );
}
